-- =============================================================================
-- gn_auto_imports : configuration des mappeurs Bretagne Vivante
-- Généré le 2026-11-19 depuis la base d'origine
--
-- À lancer APRÈS gn_auto_imports_deploy_01_structure.sql, sur un schéma sans mappeur.
--
-- Tokens : remplacés par '<TOKEN>'. Chaque export GeoNature a son propre token, fourni par
-- l'instance distante (module Export). Remplacer les 3 '<TOKEN>' avant de lancer le script,
-- ou les renseigner ensuite :
--   UPDATE gn_auto_imports.t_mappers SET token = '...' WHERE alias = 'synchro_bv';             -- export 31
--   UPDATE gn_auto_imports.t_mappers SET token = '...' WHERE alias = 'synchro_bv_mtd';         -- export 32
--   UPDATE gn_auto_imports.t_mappers SET token = '...' WHERE alias = 'synchro_bv_validations'; -- export 33
--
-- Dépendances côté base cible (à vérifier / adapter avant de lancer) :
--   * gn_meta.t_datasets.id_dataset = 3144   (JDD cible de synchro_bv, clé étrangère)
--   * gn_synthese.t_sources.id_source = 8    (constante id_source du mapping de synchro_bv)
--   * row_filter du mappeur 12 : id_dataset = 3144 écrit en dur
--   * ref_geo.l_areas.id_type 25, 46, 47, 34 (expression id_area_attachment de synchro_bv)
--
-- Les points de reprise (dates de synchro, curseurs, last_imported_id) sont remis à zéro :
-- la première exécution fera un chargement complet. Après déploiement :
--   CALL gn_auto_imports.p_run_terminal(5,  true, '{}', 10000);
--   CALL gn_auto_imports.p_run_terminal(12, true, '{}', 10000);
-- =============================================================================

\set ON_ERROR_STOP on

BEGIN;

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Data for Name: t_mappers; Type: TABLE DATA; Schema: gn_auto_imports; Owner: -
--



--
-- Data for Name: t_mapper_dependencies; Type: TABLE DATA; Schema: gn_auto_imports; Owner: -
--



--
-- Data for Name: t_mapper_fields; Type: TABLE DATA; Schema: gn_auto_imports; Owner: -
--



--
-- Name: t_mapper_fields_id_mapper_field_seq; Type: SEQUENCE SET; Schema: gn_auto_imports; Owner: -
--



--
-- Name: t_mappers_id_mapper_seq; Type: SEQUENCE SET; Schema: gn_auto_imports; Owner: -
--



SELECT setval('gn_auto_imports.t_mappers_id_mapper_seq', GREATEST((SELECT max(id_mapper) FROM gn_auto_imports.t_mappers), 1));
SELECT setval('gn_auto_imports.t_mapper_fields_id_mapper_field_seq', GREATEST((SELECT max(id_mapper_field) FROM gn_auto_imports.t_mapper_fields), 1));

-- Remise à zéro de l'état de synchronisation (chargement initial au premier run)
UPDATE gn_auto_imports.t_mappers
SET last_synchronization_date = NULL,
    last_import_date          = NULL,
    last_imported_id          = NULL,
    last_synthese_push_date   = NULL,
    push_cursor               = NULL,
    push_wm_max               = NULL
WHERE id_mapper IN (5, 7, 12);

COMMIT;
